    stretch.push(rotate2D(p0, dPhiRad * i));
    stretch.push(rotate2D(p1, dPhiRad * i));
    stretch.push(rotate2D(p2, dPhiRad * i));
    stretch.push(rotate2D(p0, dPhiRad * i));
